    page.on('requestfailed', r => console.log('   REQFAILED', r.url(), r.failure() && r.failure().errorText));
    let status = 'n/a';
    try { const resp = await page.goto(url, {waitUntil:'domcontentloaded', timeout:30000}); status = resp && resp.status(); }
    catch (e) { console.log('   GOTO_ERR', e.message.split('\n')[0]); }
