    try { tag = (await page.content()).indexOf('data-website-id') >= 0; } catch(e) {}
    await new Promise(r => setTimeout(r, 4000));
    try { um = await page.evaluate(() => typeof window.umami); } catch(e) {}
    console.log(url, '=> status=' + status, 'hasTag=' + tag, 'umami=' + um, 'sendCalls=' + sent.length);
    await page.close();
  }
